// Standalone design demonstrator: fixed examples only; no game imports, persistence or commands.
const state={screen:'home',phase:'brief',background:'technical',route:'video',wish:'保持生活自主',mode:'normal',motion:false,text:false};
const app=document.querySelector('#app');
const dialog=document.querySelector('#decision');
let opener=null;
const phases=[['brief','简报'],['plan','计划'],['decision','抉择'],['result','结果']];
const routes={
 stock:{name:'A股AI股票',title:'先决定仓位，再判断行情',intro:'现金需要留给生活，持仓要等真实成交。把研究、下单和交收放在不同步骤，浮盈始终另列。',facts:['产业与仓位','限价 / 部分成交','模拟市场持续标识'],next:'查看研究与订单的分层方式',note:'2020示例：先补研究与规则资格，报价与成交由正式规则提供。'},
 video:{name:'短视频',title:'从一件能交付的作品开始',intro:'先选受众和作品形式，再看素材、制作、客户修改与回款。播放量、有效咨询和收入分别反馈。',facts:['受众与作品','制作 / 返工 / 验收','资格后的平台变现'],next:'查看作品到回款的流程',note:'2020以手工剪辑为入口；生成式工具按真实年代与本局资格开放。'},
 course:{name:'课程',title:'卖的是能完成的教学承诺',intro:'目标学员、真实案例和班额先于收款。预售资金受保护，教学、退款与答疑分阶段显示。',facts:['目标与案例','班额 / 支持产能','预款 / 交付 / 退款'],next:'查看课程班期的层次',note:'能力尚未开放时展示准备条件，不在2020提前招生AI课程。'},
 relay:{name:'API中转',title:'服务质量，要有成本托底',intro:'供应、客户价格和实际用量组成同一张服务账单。客户充值不是利润，停站也保留旧余额。',facts:['供应故障域','价格 / 信用 / 额度','计量 / 审计 / 更正'],next:'查看服务周期与账单',note:'材料、技术与虚构用途许可分别核验，不把公开模型发布当作中转授权。'},
 deepseek:{name:'DeepSeek',title:'做生态服务，或另外谈权益',intro:'部署与培训先履约，直接投资另经明确架空选择、尽调、资格和条款谈判。股权估值与现金分开。',facts:['用途适配 / 客户','增资 / 老股 / 稀释','锁定 / 治理 / 买方'],next:'查看生态与股权的分界',note:'2020尚无相应模型能力；未来入口可发现，但不能提前签约或取得股份。'}
};
function button(label,action,cls=''){const blocked=state.mode!=='normal'&&['plan','preview','submit','next-decision','next-result'].includes(action);return `<button type="button" class="${cls}" data-action="${action}" ${blocked?'disabled':''}>${label}</button>`}
const resultCash=()=>state.background==='technical'?'42,800':'36,800';
const quarterSalary=()=>state.background==='technical'?'24,000':'18,000';
function header(){return `<header class="topbar"><button class="brand" type="button" data-screen="home">重生2020<em>AI 时代 · 人生策略</em></button><nav aria-label="主要导航">${[['quarter','本季'],['routes','经营'],['memory','记忆'],['finance','账本']].map(([s,label])=>`<button type="button" data-screen="${s}" ${state.screen===s?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="preferences"><button type="button" data-action="text" aria-pressed="${state.text}">文本模式</button><button type="button" data-action="motion" aria-pressed="${state.motion}">减少动效</button></div></header>`}
function chapter(title){return `<section class="chapter scene"><div><p class="eyebrow">第一章 / 2020 · ${state.phase==='result'?'03.31':state.phase==='decision'?'01.19':'01.01'}</p><h1 class="page-title" tabindex="-1">${title}</h1><p>${state.background==='technical'?'技术职员':'内容从业者'} · ${state.wish} · 每季四点</p></div><blockquote>未来的片段还模糊。<br>眼前的生活，可以重新选择。</blockquote></section>`}
function home(){return `<main id="main" class="home scene"><p class="eyebrow">2020 / 你的故事重新开始</p><h1 class="page-title" tabindex="-1">重生2020<span>AI 时代</span></h1><p class="intro">那时，一切还没有发生。<br>保留一份工作，做一点自己的事，<br>也可以选择不追逐每一次浪潮。</p><div class="actions">${button('从这个房间开始 →','start','primary')}${button('直接查看工作台','quarter','ghost')}</div><div class="home-meta"><span>24个季度的工作目标</span><span>五条财富路线</span><span>财富，也关乎生活</span></div><p class="home-meta">本页为新设计预览，正式游戏仍从原入口进入。</p></main>`}
function choose(){return `<main id="main" class="choose"><p class="eyebrow">第一步 / 选择起点</p><h1 class="page-title" tabindex="-1">先想一想，你想怎样生活。</h1><p class="muted">背景改变起步条件。它不会替你决定一生，也不会强迫你创业。</p><div class="backgrounds">${[['technical','技术职员','偏原型、技术学习与部署。全月在岗工资示例8000元。'],['content','内容从业者','偏表达、选题与客户沟通。全月在岗工资示例6000元。']].map(([id,label,text])=>`<button type="button" data-background="${id}" aria-pressed="${state.background===id}"><b>${label}</b><span>${text}</span></button>`).join('')}</div><label for="wish">这一次，更在意什么？</label><select id="wish"><option>保持生活自主</option><option>财务独立</option><option>经营自己的品牌</option><option>参与重要技术</option></select><div class="actions">${button('看一条记忆，走进第一季度 →','enter','primary')}${button('返回房间','home')}</div><p class="muted" style="margin-top:20px">接下来分别展示两背景首季固定财务示例；所有选择只演示设计，不改变正式存档。</p></main>`}
function stats(){const gap=state.mode==='gap',amount=gap?'0':state.phase==='result'?resultCash():state.phase==='decision'?'25,500':'26,000',spent=gap?4:['decision','result'].includes(state.phase)?3:0;return `<div class="meta-strip"><div class="cash"><span>个人账户 / 现在可花</span><strong>¥${amount}</strong></div><div><small>剩余行动 ${4-spent} / 4</small><div class="action-dots" aria-label="已用${spent}点，剩余${4-spent}点">${[0,1,2,3].map(i=>`<span class="dot ${i<spent?'spent':''}"></span>`).join('')}</div></div><small>设计预览 · 不读写真实存档</small></div>`}
function alert(){if(state.mode==='failure')return `<section class="alert" role="alert"><h3>未保存：你看到的仍是旧提交</h3><p>固定异常态示例：旧档可花¥26,000。候选单独保留，新操作暂停；不能先播放“到账成功”。</p><div class="actions">${button('查看原候选重试说明','retry','small')}${button('查看候选与旧档的区别','candidate','small')}</div></section>`;if(state.mode==='gap')return `<section class="alert" role="alert"><h3>现金为零，旧应付仍在</h3><p>独立零资源界面示例：可花¥0，剩余行动0，未结金额¥1,999.98。可停止新增或了解延期；没有免费接管。</p><div class="actions">${button('查看有限处置说明','gap-help','small')}${button('返回普通示例','normal','small')}</div></section>`;return ''}
function phaseNav(){return `<nav class="stage-nav" aria-label="季度流程示例">${phases.map(([id,label],i)=>`<button type="button" data-phase="${id}" ${state.phase===id?'aria-current="step"':''}><span>0${i+1}</span>${label}</button>`).join('')}<small>切换固定设计状态，不推进正式游戏</small></nav>`}
function mainDecision(){
 if(state.phase==='result')return `<p class="eyebrow">本季结果 / 2020 第一季度</p><h2>第一笔回款，留下了一个案例。</h2><p>不是所有变化都来自一场豪赌。工作维持了生活，一份手工交付带来了额外的收入。</p><div class="receipt"><div><small>客户回款</small><strong>¥1,300</strong></div><div><small>制作成本</small><strong>¥500</strong></div><div><small>本单净额</small><strong>＋¥800</strong></div></div><p>个人可花¥${resultCash()}。工资与生活另算；副业净额没有混入工资或股票浮盈。</p><div class="next-action">${button('看看钱从哪里来 →','finance','primary')}${button('查看下季草稿的设计','draft')}</div><details class="detail-list"><summary>展开这笔结果的解释与承诺</summary><p>固定财务样例：期初30000＋工资${state.background==='technical'?'24000':'18000'}－生活12000＋回款1300－制作500＝${state.background==='technical'?'42800':'36800'}。下季沿用只生成待确认草稿；不新增融资、招生、交易或代理授权。</p></details>`;
 if(state.phase==='decision')return `<p class="eyebrow">关键日期 / 2020.01.19</p><h2>作品做完了，客户还没有验收。</h2><p>现在要决定，是提交这份作品，还是停止继续承诺。完成、客户认可与实际到账，分成三步反馈。</p><div class="plan-line"><span>01</span><div><strong>手工制作 · 已完成示例</strong><span>1月5日开工，已发生成本500元。</span></div><b>1点</b></div><div class="plan-line"><span>02</span><div><strong>提交客户 · 等你决定</strong><span>最早1月20日复核；此刻回款仍为0。</span></div></div><div class="next-action">${button('预览提交确认 →','submit','primary')}${button('看看取消时保留什么','cancel')}</div>`;
 const planning=state.phase==='plan';return `<p class="eyebrow">${planning?'计划 / 少量有意义的安排':'本季重点 / 可以随时改'}</p><h2>保留工作，也做一点自己的事。</h2><p>${planning?'先看时间、本金和最早缺口，再确认每一份新承诺。选中一个建议并不代表已经执行。':'工资能撑起生活，手工交付给试错留一点空间。你可以沿着建议走，也可以自由安排。'}</p><div class="next-action">${button(planning?'预览资金与日期 →':'查看这份安排 →',planning?'preview':'plan','primary')}${button('自己看看五条路线','routes','link')}</div><label class="plan-line"><input type="checkbox" checked><span><strong>继续本季工作</strong><span>按实际在岗日计薪，月末到账。</span></span><b>2点</b></label><label class="plan-line"><input type="checkbox" checked><span><strong>做一份手工小单</strong><span>成本500元，14天制作，报价1300元；尚待确认。</span></span><b>1点</b></label><div class="plan-line"><span>○</span><div><strong>保留余下1点</strong><span>用于独立准备，或留给生活；不会自动安排新生意。</span></div><b>自由</b></div>`;
}
function quarter(){return `${chapter('重新安排你的时间')}<main id="main" class="workspace">${stats()}${phaseNav()}${alert()}<div class="columns"><section class="main-sheet ${['brief','plan'].includes(state.phase)?'action-first':''}">${mainDecision()}</section><aside><section class="side-section"><h3>${state.phase==='result'?'本季时间记录':'本季承诺'} <span class="badge">${state.phase==='result'?'本例已结清':'全部到期项另列'}</span></h3><ol class="timeline"><li><time>每月01日</time>${state.phase==='result'?'生活费已按月支付，共¥12,000':'生活费 ¥4,000'}<p>个人支出，不从公司预款里支付。</p></li><li><time>01.19 / 01.20</time>${state.phase==='result'?'本例作品已认可，款项已收取':'提交与客户复核'}<p>${state.phase==='result'?'完成记录不是尚未处理的待办。':'只有实际满足条件才形成回款。'}</p></li><li><time>03.31</time>本季回顾<p>净赚、浮盈、未交付与未结欠款分别显示。</p></li></ol></section><section class="side-section"><h3>一段模糊的记忆</h3><p class="quiet-note">“后来，工具改变了很多人的工作。可现在，你还需要先把生活安顿好。”</p>${button('翻开记忆 →','memory','link')}</section></aside></div><div class="bottom-note">异常态预览：${button('保存失败','failure','small')}${button('现金与行动为零','gap','small')}${button('普通状态','normal','small')}${button('例行方案草稿','draft','small')}</div></main>`}
function routePage(){const r=routes[state.route];return `${chapter('机会很多，不必每次都参加。')}<main id="main" class="workspace"><p class="eyebrow">经营 / 五条不同的路径</p><div class="route-tabs" role="tablist" aria-label="财富路线">${Object.entries(routes).map(([id,r])=>`<button type="button" role="tab" data-route="${id}" aria-selected="${state.route===id}" aria-controls="route-panel">${r.name}</button>`).join('')}</div><section class="route-detail" id="route-panel" role="tabpanel" aria-label="${r.name}"><span class="badge">2020年代门控示例</span><h2 class="page-title" tabindex="-1">${r.title}</h2><p>${r.intro}</p><div class="route-facts">${r.facts.map((f,i)=>`<div><small>0${i+1} / 独立决策层</small><strong>${f}</strong></div>`).join('')}</div><p class="muted">${r.note}</p><div class="next-action">${button(r.next,'route-info','primary')}${button('回到本季安排','quarter')}</div></section><details class="detail-list"><summary>始终可发现，不等于提前可经营</summary><p>未到年代或缺少资格时，显示真实缺项与可做的准备。正式重构仍须沿用引擎已有门控、资金与共享产能，不能用这张设计卡代替商业规则。</p></details></main>`}
function memory(){return `${chapter('记得趋势，不是答案。')}<main id="main" class="workspace"><div class="memory-grid"><article class="memory-card"><p class="eyebrow">前世记忆 / 可能有偏差</p><h2 class="page-title" tabindex="-1">有些工具，会慢慢进入日常。</h2><p>这是模糊方向，不是精确价格或购买资格。先留下一个真实案例，比背熟未来的热词更有用。</p>${button('查看可做的准备 →','routes','link')}</article><article class="memory-card"><p class="eyebrow">本局观察 / 2020.01.01</p><h2>眼前的生活是真的。</h2><p>现在拥有一份工作背景、有限的储蓄和每季四点精力。已发生的观察与前世记忆分开，后续被干预的前提需标记失效。</p></article></div><p class="muted">读新闻、翻页和收藏只改变呈现，不推进世界、不消耗随机，也不泄露隐藏真相。</p></main>`}
function finance(){const result=state.phase==='result';return `${chapter('知道钱在哪里，也知道还欠什么。')}<main id="main" class="workspace"><p class="eyebrow">个人账户 / ${result?'季末固定财务样例':'期初已发生状态'}</p><h2 class="page-title" tabindex="-1">先回答四个简单的问题。</h2><div class="financial-grid"><div><small>现在还能花</small><strong>¥${result?resultCash():'26,000'}</strong></div><div><small>本季副业净额</small><strong>${result?'＋¥800':'¥0'}</strong></div><div><small>尚未履约预款</small><strong>¥0</strong></div><div><small>已付生活费</small><strong>¥${result?'12,000':'4,000'}</strong></div></div><div class="columns"><section><h3>本季变化</h3>${(result?[['期初储蓄','¥30,000'],['工资 · 实际分月到账','＋¥'+quarterSalary()],['生活费 · 三个月','－¥12,000'],['手工单回款','＋¥1,300'],['手工制作成本','－¥500']]:[['期初储蓄','¥30,000'],['1月1日已付生活费','－¥4,000'],['尚未确认的新业务收入','¥0']]).map(([label,n])=>`<div class="ledger-row"><span>${label}</span><b>${n}</b></div>`).join('')}<details class="detail-list"><summary>展开预款、占款、应收应付与投资</summary><p>固定本例均为0。正式页面须按账户和原合同列出全部金额；证券市值、锁定私股与可花现金不能相加成一个可消费余额。</p></details></section><aside><h3>下一笔承诺</h3><p class="quiet-note">生活费按日期发生，<br>未来未知回款不能拿来偿付。</p><p class="muted">公司账目有独立入口与主体标识；在融资、停业或大额安排中，自动展开相关义务。</p></aside></div><div class="next-action">${button(result?'回看季度简报':'查看季末财务样例',result?'quarter':'result','primary')}</div></main>`}
function render(focus=true){document.body.classList.toggle('no-motion',state.motion);document.body.classList.toggle('text-mode',state.text);const content=state.screen==='home'?home():state.screen==='choose'?choose():state.screen==='routes'?routePage():state.screen==='memory'?memory():state.screen==='finance'?finance():quarter();app.innerHTML=header()+content+`<footer class="footer"><span>D01设计样稿 · 新生成场景与HTML控件 · 当前未接入正式游戏</span><span>无真实支付 / 融资 / 模型服务</span></footer>`;if(state.screen==='choose')document.querySelector('#wish').value=state.wish;if(focus){window.scrollTo(0,0);document.querySelector('.page-title')?.focus({preventScroll:true})}}
function showDialog(title,content,actionLabel=null,action=null){opener=document.activeElement;dialog.innerHTML=`<form method="dialog"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button value="cancel" aria-label="关闭对话框">×</button></div><div class="dialog-body">${content}<div class="actions">${actionLabel?button(actionLabel,action,'primary'):''}<button value="cancel">返回</button></div></div></form>`;dialog.showModal()}
dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus();else document.querySelector('.page-title')?.focus({preventScroll:true})});
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.background){state.background=target.dataset.background;render(false);document.querySelector(`[data-background="${state.background}"]`).focus();return}if(target.dataset.route){state.route=target.dataset.route;render();return}if(target.dataset.phase){state.phase=target.dataset.phase;state.mode='normal';render();return}if(target.dataset.screen){state.screen=target.dataset.screen;state.mode='normal';render();return}const action=target.dataset.action;if(!action)return;
 if(['home','quarter','routes','memory','finance'].includes(action)){state.screen=action;state.mode='normal';render();return}
 if(action==='start'){state.screen='choose';render();return}if(action==='enter'){state.screen='quarter';state.phase='brief';render();return}
 if(action==='motion'||action==='text'){state[action]=!state[action];render(false);document.querySelector(`[data-action="${action}"]`).focus();document.querySelector('#announce').textContent=`${action==='motion'?'减少动效':'文本模式'}已${state[action]?'开启':'关闭'}，只改变设计呈现。`;return}
 if(action==='plan'||action==='result'){state.screen='quarter';state.phase=action;state.mode='normal';render();return}
 if(action==='failure'||action==='gap'||action==='normal'){state.screen='quarter';state.phase='brief';state.mode=action;render();return}
 if(action==='preview'){showDialog('看清这份安排，再做决定。','<p>固定设计样例，不向正式存档提交命令。</p><div class="ledger-row"><span>执行主体</span><b>个人账户</b></div><div class="ledger-row"><span>手工制作 · 自有资金成本</span><b>¥500 / 1点</b></div><div class="ledger-row"><span>制作窗口</span><b>01.05—01.19</b></div><div class="ledger-row"><span>最早客户复核</span><b>01.20</b></div><h3>当下收到的钱仍是0。</h3><p>工作2点另行确认；剩余1点可自由安排。报价1300不等于已经验收或到账，取消后已发生成本保留。</p>','预览下一处抉择 →','next-decision');return}
 if(action==='next-decision'){dialog.close();state.phase='decision';render();return}
 if(action==='submit'){showDialog('提交后，仍要等客户复核。','<p>提交作品不会立刻增加收入。正式游戏只有命令通过、事务提交后，才发布本局结果；实际客户认可和收款另有回执。</p>','查看季末结果样例 →','next-result');return}
 if(action==='next-result'){dialog.close();state.phase='result';render();return}
 if(action==='cancel'){showDialog('停下来，也保留已经发生的事。','<p>本例已发生制作成本500元不会退回。后续不再制造新工作；原合同是否有预款、退款和未完成义务，须按实际记录核对。</p>');return}
 if(action==='draft'){showDialog('沿用到下季，只生成草稿。','<p>先展示价格、资格、预算和产能变化，再让玩家确认。融资、招生、交易和代理扩权不会被方便按钮一并接受。</p><h3>草稿 → 核对变化 → 明确确认</h3><p>这里是设计说明，不会创建正式游戏计划。</p>');return}
 if(action==='retry'||action==='candidate'){showDialog('旧提交、候选与实际保存分开。','<p>旧提交继续作为主页面依据。候选可以单独查看/导出；重试提交同一候选，不重跑命令或抽取新结果。只有数据库事务真正提交，才显示成功反馈。</p><p>此处只演示失败态的交互规范，不读写IndexedDB。</p>');return}
 if(action==='gap-help'){showDialog('零资源时仍保留有限处置。','<p>停止可控新增、查看原义务与延期后果都应可达。支付受实际可花现金约束，不能用未来工资、预款或免费接管填平缺口。</p>');return}
 if(action==='route-info'){const r=routes[state.route];showDialog(r.name+' / 独立操作层次',`<p>${r.intro}</p><h3>${r.facts.join(' → ')}</h3><p>${r.note}</p><p>本轮为设计样稿，正式接线由D02使用原有真实经营命令完成。</p>`)}
});
document.addEventListener('change',event=>{if(event.target.id==='wish')state.wish=event.target.value});
document.addEventListener('keydown',event=>{const current=event.target.closest('[data-route]');if(!current||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const ids=Object.keys(routes),index=ids.indexOf(state.route);state.route=event.key==='Home'?ids[0]:event.key==='End'?ids.at(-1):ids[(index+(event.key==='ArrowRight'?1:-1)+ids.length)%ids.length];render(false);document.querySelector(`[data-route="${state.route}"]`).focus()});
render(false);
